export const saveMessage = async ({
  id,
  content,
  history_id,
  name,
  role,
  images,
  source,
  discoSkillComment,
  generationInfo,
  metadataExtra,
  message_type,
  clusterId,
  modelId,
  modelImage,
  modelName,
  parent_message_id,
  reasoning_time_taken,
  time,
  documents,
  serverMessageId,
  createdAt: createdAtOverride
}: {
  id?: string
  history_id: string
  name: string
  role: string
  content: string
  images: string[]
  source?: any[]
  time?: number
  message_type?: string
  discoSkillComment?: Message["discoSkillComment"]
  clusterId?: string
  modelId?: string
  generationInfo?: any
  metadataExtra?: Record<string, unknown>
  reasoning_time_taken?: number
  modelName?: string
  modelImage?: string
  parent_message_id?: string | null
  documents?: ChatDocuments
  serverMessageId?: string | null
  createdAt?: number
}) => {
  const messageId = id ?? generateID()
  let createdAt =
    typeof createdAtOverride === "number"
      ? createdAtOverride
      : Date.now()
  if (typeof createdAtOverride !== "number" && time) {
    createdAt += time
  }
  const message: Message = {
    id: messageId,
    history_id,
    name,
    role,
    content,
    images,
    createdAt,
    sources: source,
    messageType: message_type,
    clusterId,
    modelId,
    generationInfo: generationInfo,
    metadataExtra,
    reasoning_time_taken,
    modelName,
    modelImage,
    parent_message_id: parent_message_id ?? null,
    documents,
    discoSkillComment,
    serverMessageId: serverMessageId ?? undefined
  }
  const db = new PageAssistDatabase()
  await db.addMessage(message)
  return message
}

