const extractToolCalls = (generationInfo: unknown): ToolCall[] | undefined => {
  if (!generationInfo || typeof generationInfo !== "object") return undefined
  const candidate =
    (generationInfo as any).tool_calls ?? (generationInfo as any).toolCalls
  return Array.isArray(candidate) ? (candidate as ToolCall[]) : undefined
}

export const runChatPipeline = async <TParams extends ChatModeParamsBase>(
  mode: ChatModeDefinition<TParams>,
  message: string,
  image: string,
  isRegenerate: boolean,
  messages: Message[],
  history: ChatHistory,
  signal: AbortSignal,
  params: TParams
): Promise<ChatSubmitResult> => {
  const {
    selectedModel: rawSelectedModel,
    toolChoice,
    setMessages,
    saveMessageOnSuccess,
    saveMessageOnError,
    setHistory,
    setIsProcessing,
    setStreaming,
    setAbortController,
    historyId,
    setHistoryId,
    clusterId,
    userMessageType,
    assistantMessageType,
    modelIdOverride: rawModelIdOverride,
    userMessageId,
    assistantMessageId,
    userParentMessageId,
    assistantParentMessageId,
    documents,
    regenerateFromMessage,
    imageEventSyncPolicy,
    conversationId
  } = params
  const selectedModelSelection =
    parseProviderQualifiedModelSelection(rawSelectedModel)
  const selectedModel =
    selectedModelSelection.modelId || rawSelectedModel
  const modelIdOverride = rawModelIdOverride
    ? String(rawModelIdOverride).trim()
    : undefined

  const resolvedAssistantMessageId = assistantMessageId ?? generateID()
  const resolvedUserMessageId =
    !isRegenerate ? userMessageId ?? generateID() : undefined
  const createdAt = Date.now()
  let generateMessageId = resolvedAssistantMessageId
  const modelInfo = await getModelNicknameByID(selectedModel)

  const isSharedCompareUser = userMessageType === "compare:user"
  const isImageGenerationTurn =
    userMessageType === IMAGE_GENERATION_USER_MESSAGE_TYPE ||
    assistantMessageType === IMAGE_GENERATION_ASSISTANT_MESSAGE_TYPE
  const resolvedModelId = modelIdOverride || selectedModel
  const userModelId = isSharedCompareUser ? undefined : resolvedModelId
  const fallbackParentMessageId = getLastUserMessageId(messages)
  const resolvedAssistantParentMessageId =
    assistantParentMessageId ??
    (isRegenerate
      ? regenerateFromMessage?.parentMessageId ?? fallbackParentMessageId
      : resolvedUserMessageId ?? null)
  const regenerateVariants =
    isRegenerate && regenerateFromMessage
      ? normalizeMessageVariants(regenerateFromMessage)
      : []
  // The variant that was active before this regenerate began. Used to restore
  // prior state if the regenerate is cancelled before any token arrives.
  const priorActiveVariantIndex =
    isRegenerate && regenerateFromMessage && regenerateVariants.length > 0
      ? Math.min(
          Math.max(
            0,
            typeof regenerateFromMessage.activeVariantIndex === "number"
              ? regenerateFromMessage.activeVariantIndex
              : regenerateVariants.length - 1
          ),
          regenerateVariants.length - 1
        )
      : 0

  const context: ChatModeContext<TParams> = {
    ...params,
    selectedModel,
    modelIdOverride,
    message,
    image,
    isRegenerate,
    messages,
    history,
    signal,
    createdAt,
    generateMessageId,
    resolvedUserMessageId,
    resolvedAssistantMessageId,
    resolvedAssistantParentMessageId,
    resolvedModelId,
    userModelId,
    modelInfo,
    regenerateVariants
  }

  let modelClient: Awaited<ReturnType<typeof pageAssistModel>> | undefined
  let fullText = ""
  let contentToSave = ""
  let timetaken = 0
  let promptContent: string | undefined = undefined
  let promptId: string | undefined = undefined
  let streamingTimer: ReturnType<typeof setTimeout> | null = null
  let lastStreamingUpdateAt = 0
  let pendingStreamingText = ""
  let pendingReasoningTime = 0
  const setMessagesWithTransition = (
    messagesOrUpdater: Message[] | ((prev: Message[]) => Message[])
  ) => {
    startTransition(() => {
      setMessages(messagesOrUpdater)
    })
  }
  const setHistorySafely = (nextHistory: ChatHistory) => {
    if (typeof setHistory === "function") {
      setHistory(nextHistory)
      return
    }
    const fallback = useStoreMessageOption.getState().setHistory
    if (typeof fallback === "function") {
      fallback(nextHistory)
      return
    }
    if (!didLogPipelineSetHistoryMissing) {
      didLogPipelineSetHistoryMissing = true
      console.error("[chat] runChatPipeline could not resolve setHistory setter", {
        setHistoryType: typeof setHistory
      })
    }
  }

  const normalizeImageVariantsForMessage = (messageEntry: Message): Message => {
    if (!isImageGenerationTurn) {
      return messageEntry
    }

    const variants = Array.isArray(messageEntry.variants)
      ? (messageEntry.variants as MessageVariant[])
      : []
    const normalized = normalizeImageGenerationVariantBundle({
      messageId: messageEntry.id,
      messageGenerationInfo: messageEntry.generationInfo,
      variants,
      activeVariantIndex:
        typeof messageEntry.activeVariantIndex === "number"
          ? messageEntry.activeVariantIndex
          : undefined,
      fallbackCreatedAt: createdAt,
      hasVisibleVariant:
        variants.length > 0 ||
        (Array.isArray(messageEntry.images) && messageEntry.images.length > 0)
    })

    if (variants.length === 0) {
      return {
        ...messageEntry,
        generationInfo: normalized.generationInfo ?? messageEntry.generationInfo
      }
    }

    const activeVariant = normalized.variants[
      normalized.activeVariantIndex
    ] as MessageVariant | undefined
    const withNormalizedVariants: Message = {
      ...messageEntry,
      variants: normalized.variants as MessageVariant[],
      activeVariantIndex: normalized.activeVariantIndex,
      generationInfo: normalized.generationInfo ?? messageEntry.generationInfo
    }
    if (!activeVariant) {
      return withNormalizedVariants
    }

    return applyVariantToMessage(
      withNormalizedVariants,
      activeVariant,
      normalized.activeVariantIndex
    )
  }

  const applyMetadataExtra = (
    messageEntry: Message,
    metadataExtra?: MessageMetadataExtra
  ): Message => {
    if (!metadataExtra) return messageEntry
    return {
      ...messageEntry,
      metadataExtra: {
        ...(messageEntry.metadataExtra ?? {}),
        ...metadataExtra
      }
    }
  }

  const flushStreamingUpdate = () => {
    streamingTimer = null
    lastStreamingUpdateAt = Date.now()
    setMessagesWithTransition((prev) =>
      prev.map((msg) =>
        msg.id === generateMessageId
          ? updateActiveVariant(msg, {
              message: pendingStreamingText,
              reasoning_time_taken: pendingReasoningTime
            })
          : msg.id === resolvedUserMessageId && modelClient?.userServerMessageId
            ? { ...msg, serverMessageId: modelClient.userServerMessageId }
            : msg
      )
    )
  }

  // Throttle streaming UI updates to keep the input responsive.
  const scheduleStreamingUpdate = (text: string, reasoningTime: number) => {
    pendingStreamingText = text
    pendingReasoningTime = reasoningTime
    if (streamingTimer != null) return
    const now = Date.now()
    const elapsed = now - lastStreamingUpdateAt
    const delay = Math.max(0, STREAMING_UPDATE_INTERVAL_MS - elapsed)
    streamingTimer = setTimeout(flushStreamingUpdate, delay)
  }

  const cancelStreamingUpdate = () => {
    if (streamingTimer == null) return
    clearTimeout(streamingTimer)
    streamingTimer = null
  }

  const abortCancelStreamingUpdate = () => cancelStreamingUpdate()
  signal.addEventListener("abort", abortCancelStreamingUpdate)

  // Regenerate appends a new (initially empty) variant. If the regenerate is
  // cancelled before any token arrives, drop that empty variant and restore the
  // previously-active variant instead of leaving an empty interrupted variant.
  // Returns true when it handled the discard (so callers can finalize as
  // skipped), false when there was nothing to restore.
  const discardEmptyRegenerateVariant = (): boolean => {
    if (!isRegenerate) return false
    if (regenerateVariants.length === 0) {
      // No prior variant to restore to: drop the empty assistant message.
      setMessagesWithTransition((prev) =>
        prev.filter((msg) => msg.id !== generateMessageId)
      )
      return true
    }
    const restoreIndex = Math.min(
      Math.max(0, priorActiveVariantIndex),
      regenerateVariants.length - 1
    )
    const restoredVariant = regenerateVariants[restoreIndex]
    setMessagesWithTransition((prev) =>
      prev.map((msg) => {
        if (msg.id !== generateMessageId) return msg
        const variants = Array.isArray(msg.variants)
          ? (msg.variants as MessageVariant[])
          : []
        // Only trim when the appended empty stub is still the trailing variant.
        const trimmed =
          variants.length > regenerateVariants.length
            ? variants.slice(0, regenerateVariants.length)
            : variants
        const base: Message = {
          ...msg,
          variants: trimmed,
          activeVariantIndex: restoreIndex
        }
        return restoredVariant
          ? applyVariantToMessage(base, restoredVariant, restoreIndex)
          : base
      })
    )
    return true
  }

  if (mode.setupMessages) {
    const setup = mode.setupMessages(context)
    generateMessageId = setup.targetMessageId
    context.generateMessageId = generateMessageId
    context.resolvedAssistantMessageId = generateMessageId
    if (typeof setup.initialFullText === "string") {
      fullText = setup.initialFullText
      contentToSave = setup.initialFullText
    }
  } else {
    if (!mode.buildAssistantMessage || !mode.buildUserMessage) {
      throw new Error(`Chat mode "${mode.id}" is missing message builders.`)
    }
    setMessagesWithTransition((prev) => {
      const assistantStub = mode.buildAssistantMessage!(context)
      if (!isRegenerate) {
        const userMessageEntry = applyMetadataExtra(
          mode.buildUserMessage!(context),
          params.userMetadataExtra
        )
        const existingUserIndex = resolvedUserMessageId
          ? prev.findIndex(
              (messageEntry) =>
                messageEntry.id === resolvedUserMessageId &&
                !messageEntry.isBot
            )
          : -1
        if (existingUserIndex >= 0) {
          const next = [...prev]
          const existingUserMessage = next[existingUserIndex]
          next[existingUserIndex] = applyMetadataExtra(
            {
              ...existingUserMessage,
              ...userMessageEntry,
              id: existingUserMessage.id,
              createdAt:
                existingUserMessage.createdAt ?? userMessageEntry.createdAt,
              metadataExtra: existingUserMessage.metadataExtra
            },
            params.userMetadataExtra
          )
          return [...next, assistantStub]
        }
        return [...prev, userMessageEntry, assistantStub]
      }
      return [...prev, assistantStub]
    })

    if (regenerateVariants.length > 0) {
      setMessagesWithTransition((prev) => {
        const next = [...prev]
        const lastIndex = next.findLastIndex(
          (msg) => msg.id === resolvedAssistantMessageId
        )
        if (lastIndex >= 0) {
          const stub = next[lastIndex]
          const variants = [
            ...regenerateVariants,
            buildMessageVariant(stub)
          ]
          next[lastIndex] = normalizeImageVariantsForMessage({
            ...stub,
            variants,
            activeVariantIndex: variants.length - 1
          })
        }
        return next
      })
    }
  }

  try {
    const preflight = mode.preflight ? await mode.preflight(context) : null
    if (preflight?.handled) {
      fullText = preflight.fullText
      const sources = preflight.sources ?? []
      const images = preflight.images ?? []
      const toolCalls = extractToolCalls(preflight.generationInfo)
      applyMcpModuleDisclosureFromToolCalls(toolCalls)
      const nextHistory = mode.updateHistory
        ? mode.updateHistory(context, fullText)
        : preflight.skipHistoryAppend
          ? history
        : ([
            ...history,
            { role: "user", content: message, image },
            { role: "assistant", content: fullText }
          ] as ChatHistory)
      const preflightGenerationInfoForSave = (() => {
        if (!isImageGenerationTurn) {
          return preflight.generationInfo
        }

        const normalizedBundle = normalizeImageGenerationVariantBundle({
          messageId: resolvedAssistantMessageId,
          messageGenerationInfo: preflight.generationInfo,
          variants:
            regenerateVariants.length > 0
              ? [
                  ...regenerateVariants,
                  {
                    id: resolvedAssistantMessageId,
                    generationInfo: preflight.generationInfo
                  }
                ]
              : [],
          activeVariantIndex:
            regenerateVariants.length > 0 ? regenerateVariants.length : 0,
          fallbackCreatedAt: createdAt,
          hasVisibleVariant: images.length > 0
        })
        return normalizedBundle.generationInfo ?? preflight.generationInfo
      })()

      setMessagesWithTransition((prev) =>
        prev.map((msg) =>
          msg.id === generateMessageId
            ? normalizeImageVariantsForMessage(
                updateActiveVariant(msg, {
                  message: fullText,
                  sources,
                  images,
                  generationInfo: preflightGenerationInfoForSave,
                  toolCalls,
                  reasoning_time_taken: timetaken
                })
              )
            : msg
        )
      )
      setHistorySafely(nextHistory)

      await saveMessageOnSuccess({
        historyId,
        setHistoryId,
        isRegenerate,
        selectedModel,
        message,
        image,
        fullText,
        source: sources,
        assistantImages: images,
        userMessageType,
        assistantMessageType,
        clusterId,
        modelId: resolvedModelId,
        userModelId,
        userMessageId: resolvedUserMessageId,
        assistantMessageId: resolvedAssistantMessageId,
        userParentMessageId: userParentMessageId ?? null,
        assistantParentMessageId: resolvedAssistantParentMessageId ?? null,
        documents,
        isContinue: mode.isContinue,
        generationInfo: preflightGenerationInfoForSave as any,
        prompt_content: preflight.promptContent,
        prompt_id: preflight.promptId,
        reasoning_time_taken: timetaken,
        saveToDb: preflight.saveToDb ?? false,
        conversationId: preflight.conversationId,
        imageEventSyncPolicy,
        scopeSignal: params.servicePromptSnapshot?.scopeSignal,
        scopeInvalidatedSignal:
          params.servicePromptSnapshot?.scopeInvalidatedSignal,
        requestScope: params.servicePromptSnapshot?.requestScope,
        userMetadataExtra: !isRegenerate ? params.userMetadataExtra : undefined
      })
      if (
        params.servicePromptSnapshot &&
        params.servicePromptSnapshot.scopeInvalidatedSignal.aborted
      ) {
        const error = new Error("Request scope changed")
        error.name = "AbortError"
        throw error
      }
      return chatSubmitSubmitted()
    }

    const promptData = await mode.preparePrompt(context)
    if (params.dynamicUIRequest?.renderer === "openui") {
      promptData.chatHistory = [
        { role: "system", content: OPENUI_SYSTEM_PROMPT },
        ...promptData.chatHistory
      ]
    }
    const steeringSnippet = buildMessageSteeringSnippet(
      context.messageSteering || {
        continueAsUser: false,
        impersonateUser: false,
        forceNarrate: false
      },
      context.messageSteeringPrompts
    )
    if (steeringSnippet) {
      promptData.chatHistory = [
        ...promptData.chatHistory,
        { role: "system", content: steeringSnippet }
      ]
    }
    promptContent = promptData.promptContent
    promptId = promptData.promptId
    const sources = promptData.sources ?? []
    const humanMessage = promptData.humanMessage

    modelClient = await pageAssistModel({
      model: selectedModel,
      toolChoice,
      conversationId,
      researchContext: context.researchContext,
      requestScope: params.servicePromptSnapshot?.requestScope
    })

    let generationInfo: unknown = undefined
    const chunks = await modelClient.stream(
      humanMessage
        ? [...promptData.chatHistory, humanMessage]
        : [...promptData.chatHistory],
      {
        signal,
        callbacks: [
          {
            handleLLMEnd(output: unknown): void {
              const extractor =
                mode.extractGenerationInfo ?? defaultExtractGenerationInfo
              generationInfo = extractor(output)
            }
          }
        ]
      }
    )

    let count = 0
    let reasoningStartTime: Date | null = null
    let reasoningEndTime: Date | null = null
    let apiReasoning = false
    let streamTransportInterrupted = false
    let streamTransportInterruptionReason: string | null = null

    for await (const chunk of chunks) {
      if (signal.aborted) break

      const interruptionEvent =
        chunk && typeof chunk === "object" && !Array.isArray(chunk)
          ? (chunk as Record<string, unknown>)
          : null
      if (
        typeof interruptionEvent?.event === "string" &&
        interruptionEvent.event.toLowerCase() ===
          "stream_transport_interrupted"
      ) {
        streamTransportInterrupted = true
        const detail =
          typeof interruptionEvent.detail === "string"
            ? interruptionEvent.detail.trim()
            : ""
        streamTransportInterruptionReason =
          detail.length > 0 ? detail : streamTransportInterruptionReason
        continue
      }

      const chunkState = consumeStreamingChunk(
        { fullText, contentToSave, apiReasoning },
        chunk as StreamingChunk
      )
      fullText = chunkState.fullText
      contentToSave = chunkState.contentToSave
      apiReasoning = chunkState.apiReasoning

      if (isReasoningStarted(fullText) && !reasoningStartTime) {
        reasoningStartTime = new Date()
      }

      if (
        reasoningStartTime &&
        !reasoningEndTime &&
        isReasoningEnded(fullText)
      ) {
        reasoningEndTime = new Date()
        const reasoningTime =
          reasoningEndTime.getTime() - reasoningStartTime.getTime()
        timetaken = reasoningTime
      }

      if (count === 0) {
        setIsProcessing(true)
      }

      scheduleStreamingUpdate(`${fullText}▋`, timetaken)
      count++
    }

    // User abort: never fall through to the success path (which would save the
    // partial as a complete answer). Route through the interrupted path, or
    // discard entirely if nothing was streamed before the abort.
    if (signal.aborted) {
      cancelStreamingUpdate()
      signal.removeEventListener("abort", abortCancelStreamingUpdate)
      const abortedBeforeAnyContent =
        count === 0 &&
        fullText.trim().length === 0 &&
        !isImageGenerationTurn
      if (abortedBeforeAnyContent) {
        if (isRegenerate) {
          // Regenerate cancelled before any token arrived: discard the empty
          // new variant and restore the previously-active variant instead of
          // persisting an empty interrupted variant.
          if (discardEmptyRegenerateVariant()) {
            return chatSubmitSkipped("Request cancelled")
          }
        } else {
          // Nothing arrived before the user aborted: drop the empty assistant
          // stub instead of persisting an empty/error bubble.
          setMessagesWithTransition((prev) =>
            prev.filter((msg) => msg.id !== generateMessageId)
          )
          return chatSubmitSkipped("Request cancelled")
        }
      }
      const abortError = new Error("Request cancelled")
      abortError.name = "AbortError"
      throw abortError
    }

    if (
      !signal.aborted &&
      count === 0 &&
      fullText.trim().length === 0 &&
      !isImageGenerationTurn
    ) {
      throw new Error(
        streamTransportInterruptionReason ||
          EMPTY_RESPONSE_ERROR_MESSAGE
      )
    }

    cancelStreamingUpdate()
    signal.removeEventListener("abort", abortCancelStreamingUpdate)
    const toolCalls = extractToolCalls(generationInfo)
    if (
      !signal.aborted &&
      fullText.trim().length === 0 &&
      (!Array.isArray(toolCalls) || toolCalls.length === 0) &&
      !isImageGenerationTurn
    ) {
      throw new Error(EMPTY_RESPONSE_ERROR_MESSAGE)
    }
    if (
      isReasoningOnlyResponse(fullText) &&
      (!Array.isArray(toolCalls) || toolCalls.length === 0) &&
      !isImageGenerationTurn
    ) {
      throw new Error(MISSING_FINAL_ANSWER_MESSAGE)
    }
    applyMcpModuleDisclosureFromToolCalls(toolCalls)
    const finalGenerationInfo = streamTransportInterrupted
      ? {
          ...(generationInfo && typeof generationInfo === "object" && !Array.isArray(generationInfo)
            ? generationInfo
            : {}),
          interrupted: true,
          partialResponseSaved: true,
          streamTransportInterrupted: true,
          streamTransportInterruptionReason:
            streamTransportInterruptionReason ||
            "Stream transport interrupted; partial response saved."
        }
      : generationInfo
    const dynamicUIEnvelope =
      params.dynamicUIRequest?.renderer === "openui"
        ? buildDynamicUIEnvelope("openui", fullText)
        : null
    const assistantMetadataExtra = dynamicUIEnvelope
      ? { dynamic_ui: dynamicUIEnvelope }
      : undefined
    setMessagesWithTransition((prev) =>
      prev.map((msg) =>
        msg.id === generateMessageId
          ? normalizeImageVariantsForMessage(
              updateActiveVariant(msg, {
                message: fullText,
                serverMessageId: modelClient.serverMessageId,
                sources,
                generationInfo: finalGenerationInfo,
                toolCalls,
                reasoning_time_taken: timetaken,
                ...(assistantMetadataExtra
                  ? { metadataExtra: assistantMetadataExtra }
                  : {})
              })
            )
          : msg.id === resolvedUserMessageId && modelClient?.userServerMessageId
            ? { ...msg, serverMessageId: modelClient.userServerMessageId }
            : msg
      )
    )

    // Stream transport interrupted mid-answer (extension port dropped after the
    // first byte): the assistant message is already marked interrupted above.
    // Persist the partial via the interrupted/error path — never
    // saveMessageOnSuccess, which would finalize a truncated answer as COMPLETE
    // and mirror it to the server. This mirrors character chat's handling of the
    // same `stream_transport_interrupted` sentinel.
    if (streamTransportInterrupted) {
      const interruptionReason =
        streamTransportInterruptionReason ||
        "Stream transport interrupted; partial response saved."
      await saveMessageOnError({
        e: new Error(interruptionReason),
        botMessage: fullText,
        history,
        historyId,
        image,
        selectedModel,
        setHistory: setHistorySafely,
        setHistoryId,
        userMessage: message,
        isRegenerating: isRegenerate,
        userMessageType,
        assistantMessageType,
        clusterId,
        modelId: resolvedModelId,
        userModelId,
        userMessageId: resolvedUserMessageId,
        userServerMessageId: modelClient?.userServerMessageId,
        assistantServerMessageId: modelClient?.serverMessageId,
        assistantMessageId: resolvedAssistantMessageId,
        userParentMessageId: userParentMessageId ?? null,
        assistantParentMessageId: resolvedAssistantParentMessageId ?? null,
        documents,
        isContinue: mode.isContinue,
        prompt_content: promptContent,
        prompt_id: promptId,
        scopeSignal: params.servicePromptSnapshot?.scopeSignal,
        scopeInvalidatedSignal:
          params.servicePromptSnapshot?.scopeInvalidatedSignal,
        requestScope: params.servicePromptSnapshot?.requestScope,
        shouldAbortForScopeChange: params.discardCurrentTurnOnAbort,
        userMetadataExtra: !isRegenerate ? params.userMetadataExtra : undefined,
        assistantMetadataExtra
      })
      if (params.discardCurrentTurnOnAbort?.() === true) {
        setMessages(messages)
        setHistorySafely(history)
        return chatSubmitSkipped("Request scope changed")
      }
      return chatSubmitSkipped(interruptionReason)
    }

    setHistorySafely(
      mode.updateHistory
        ? mode.updateHistory(context, fullText)
        : ([
            ...history,
            { role: "user", content: message, image },
            { role: "assistant", content: fullText }
          ] as ChatHistory)
    )

    await saveMessageOnSuccess({
      historyId,
      setHistoryId,
      isRegenerate,
      selectedModel,
      message,
      image,
      fullText,
      source: sources,
      userMessageType,
      assistantMessageType,
      clusterId,
      modelId: resolvedModelId,
      userModelId,
      userMessageId: resolvedUserMessageId,
      userServerMessageId: modelClient?.userServerMessageId,
      assistantMessageId: resolvedAssistantMessageId,
      userParentMessageId: userParentMessageId ?? null,
      assistantParentMessageId: resolvedAssistantParentMessageId ?? null,
      documents,
      isContinue: mode.isContinue,
      generationInfo: finalGenerationInfo as any,
      prompt_content: promptContent,
      prompt_id: promptId,
      reasoning_time_taken: timetaken,
      saveToDb: Boolean(modelClient.saveToDb),
      conversationId: modelClient.conversationId,
      assistantServerMessageId: modelClient.serverMessageId,
      imageEventSyncPolicy,
      scopeSignal: params.servicePromptSnapshot?.scopeSignal,
      scopeInvalidatedSignal:
        params.servicePromptSnapshot?.scopeInvalidatedSignal,
      requestScope: params.servicePromptSnapshot?.requestScope,
      userMetadataExtra: !isRegenerate ? params.userMetadataExtra : undefined,
      assistantMetadataExtra
    })
    if (
      params.servicePromptSnapshot &&
      params.servicePromptSnapshot.scopeInvalidatedSignal.aborted
    ) {
      const error = new Error("Request scope changed")
      error.name = "AbortError"
      throw error
    }
    return chatSubmitSubmitted()
  } catch (e) {
    cancelStreamingUpdate()
    signal.removeEventListener("abort", abortCancelStreamingUpdate)
    if (isRequestConfigScopeChangedError(e)) {
      setMessages(messages)
      setHistorySafely(history)
      return chatSubmitSkipped("Request scope changed")
    }
    const isAbort = signal.aborted || isAbortLikeError(e)
    if (isAbort && params.discardCurrentTurnOnAbort?.() === true) {
      setMessages(messages)
      setHistorySafely(history)
      return chatSubmitSkipped("Request cancelled")
    }
    if (isAbort && !isImageGenerationTurn && fullText.trim().length === 0) {
      // Aborted before any content arrived (the pull was still in flight).
      if (isRegenerate) {
        // Regenerate: discard the empty new variant and restore the
        // previously-active variant instead of persisting an empty interrupted
        // variant.
        if (discardEmptyRegenerateVariant()) {
          return chatSubmitSkipped("Request cancelled")
        }
      } else {
        // Drop the empty assistant stub instead of persisting an empty bubble.
        setMessagesWithTransition((prev) =>
          prev.filter((msg) => msg.id !== generateMessageId)
        )
        return chatSubmitSkipped("Request cancelled")
      }
    }
    const assistantContent = isAbort
      ? fullText
      : buildAssistantErrorContent(fullText, e)
    const assistantErrorDynamicUIEnvelope =
      params.dynamicUIRequest?.renderer === "openui"
        ? buildDynamicUIEnvelope("openui", assistantContent)
        : null
    const assistantErrorMetadataExtra = assistantErrorDynamicUIEnvelope
      ? { dynamic_ui: assistantErrorDynamicUIEnvelope }
      : undefined
    const interruptionReason = isAbort
      ? "Request cancelled"
      : e instanceof Error && e.message.trim().length > 0
        ? e.message
        : "Something went wrong."
    setMessagesWithTransition((prev) =>
      prev.map((msg) =>
        msg.id === generateMessageId
          ? normalizeImageVariantsForMessage(
              updateActiveVariant(msg, {
                message: assistantContent,
                ...(modelClient?.serverMessageId ? { serverMessageId: modelClient.serverMessageId } : {}),
                generationInfo: {
                  ...(msg.generationInfo || {}),
                  interrupted: true,
                  interruptionReason,
                  interruptedAt: Date.now()
                }
              })
            )
          : msg.id === resolvedUserMessageId && modelClient?.userServerMessageId
            ? { ...msg, serverMessageId: modelClient.userServerMessageId }
            : msg
      )
    )

    let errorSave: string | null
    try {
      errorSave = await saveMessageOnError({
        e,
        botMessage: assistantContent,
        history,
        historyId,
        image,
        selectedModel,
        setHistory: setHistorySafely,
        setHistoryId,
        userMessage: message,
        isRegenerating: isRegenerate,
        userMessageType,
        assistantMessageType,
        clusterId,
        modelId: resolvedModelId,
        userModelId,
        userMessageId: resolvedUserMessageId,
        userServerMessageId: modelClient?.userServerMessageId,
        assistantServerMessageId: modelClient?.serverMessageId,
        assistantMessageId: resolvedAssistantMessageId,
        userParentMessageId: userParentMessageId ?? null,
        assistantParentMessageId: assistantParentMessageId ?? null,
        documents,
        isContinue: mode.isContinue,
        prompt_content: promptContent,
        prompt_id: promptId,
        scopeSignal: params.servicePromptSnapshot?.scopeSignal,
        scopeInvalidatedSignal:
          params.servicePromptSnapshot?.scopeInvalidatedSignal,
        requestScope: params.servicePromptSnapshot?.requestScope,
        shouldAbortForScopeChange: params.discardCurrentTurnOnAbort,
        userMetadataExtra: !isRegenerate ? params.userMetadataExtra : undefined,
        assistantMetadataExtra: assistantErrorMetadataExtra
      })
    } catch (persistenceError) {
      if (
        isRequestConfigScopeChangedError(persistenceError) ||
        params.discardCurrentTurnOnAbort?.() === true
      ) {
        setMessages(messages)
        setHistorySafely(history)
        return chatSubmitSkipped("Request scope changed")
      }
      throw persistenceError
    }

    if (params.discardCurrentTurnOnAbort?.() === true) {
      setMessages(messages)
      setHistorySafely(history)
      return chatSubmitSkipped("Request scope changed")
    }

    if (isAbort) {
      return chatSubmitSkipped(interruptionReason)
    }

    if (!errorSave) {
      throw e
    }
    return chatSubmitFailed(interruptionReason)
  } finally {
    signal.removeEventListener("abort", abortCancelStreamingUpdate)
    // Only reset the shared streaming flag / controller if this turn still owns
    // it. A newer in-flight turn may have replaced the controller; clobbering it
    // would re-enable the send button and orphan the newer turn's Stop button.
    const stillOwnsTurn = params.releaseAbortControllerIfOwned
      ? params.releaseAbortControllerIfOwned(signal)
      : true
    if (stillOwnsTurn) {
      setIsProcessing(false)
      setStreaming(false)
      setAbortController(null)
    }
  }
}

import {
  BaseMessage,
  AIMessage,
  HumanMessage,
  SystemMessage,
  ToolMessage
} from "@/types/messages"
import {
  tldwChat,
  ChatMessage,
  type ChatCompletionContentPart,
  type ChatResearchContext
} from "@/services/tldw"
import type { ToolCall } from "@/types/tool-calls"
import { publishChatLoopEvent } from "@/services/chat-loop/bridge"
import { extractChatLoopEvent } from "@/services/chat-loop/stream"
import { extractStreamTransportInterruption } from "@/utils/extract-token-from-chunk"
import type { ChatRequestDebugMetadata } from "@/services/tldw/chat-request-debug"
import type { ServicePromptRequestScope } from "@/services/tldw/domains/service-prompts"

export interface ChatTldwOptions {
  model: string
  routing?: {
    strategy?: "llm_router" | "rules_router"
    objective?: "highest_quality" | "lowest_cost" | "lowest_latency" | "balanced"
    mode?: "per_turn" | "sticky_session"
    cross_provider?: boolean
    failure_mode?: "fallback_then_error" | "error"
  }
  temperature?: number
  maxTokens?: number
  topP?: number
  frequencyPenalty?: number
  presencePenalty?: number
  systemPrompt?: string
  streaming?: boolean
  reasoningEffort?: "low" | "medium" | "high"
  toolChoice?: "auto" | "none" | "required"
  tools?: Record<string, unknown>[]
  supportsMultimodal?: boolean
  saveToDb?: boolean
  conversationId?: string
  historyMessageLimit?: number
  historyMessageOrder?: string
  slashCommandInjectionMode?: string
  apiProvider?: string
  extraHeaders?: Record<string, unknown>
  extraBody?: Record<string, unknown>
  researchContext?: ChatResearchContext
  chatDebugMetadata?: ChatRequestDebugMetadata
  requestScope?: ServicePromptRequestScope
}

export class ChatTldw {
  model: string
  routing?: ChatTldwOptions["routing"]
  temperature?: number
  maxTokens?: number
  topP?: number
  frequencyPenalty?: number
  presencePenalty?: number
  systemPrompt?: string
  streaming: boolean
  reasoningEffort?: "low" | "medium" | "high"
  toolChoice?: "auto" | "none" | "required"
  tools?: Record<string, unknown>[]
  supportsMultimodal: boolean
  saveToDb?: boolean
  conversationId?: string
  serverMessageId?: string
  userServerMessageId?: string
  historyMessageLimit?: number
  historyMessageOrder?: string
  slashCommandInjectionMode?: string
  apiProvider?: string
  extraHeaders?: Record<string, unknown>
  extraBody?: Record<string, unknown>
  researchContext?: ChatResearchContext
  chatDebugMetadata?: ChatRequestDebugMetadata
  requestScope?: ServicePromptRequestScope

  constructor(options: ChatTldwOptions) {
    // Normalize model id: drop internal prefix like "tldw:" so server receives provider/model
    this.model = String(options.model || '').replace(/^tldw:/, '')
    this.routing = options.routing
    this.temperature = options.temperature ?? 0.7
    this.maxTokens = options.maxTokens
    this.topP = options.topP ?? 1
    this.frequencyPenalty = options.frequencyPenalty ?? 0
    this.presencePenalty = options.presencePenalty ?? 0
    this.systemPrompt = options.systemPrompt
    this.streaming = options.streaming ?? false
    this.reasoningEffort = options.reasoningEffort
    this.toolChoice = options.toolChoice
    this.tools = options.tools
    this.supportsMultimodal = Boolean(options.supportsMultimodal)
    this.saveToDb = options.saveToDb
    this.conversationId = options.conversationId
    this.historyMessageLimit = options.historyMessageLimit
    this.historyMessageOrder = options.historyMessageOrder
    this.slashCommandInjectionMode = options.slashCommandInjectionMode
    this.apiProvider = options.apiProvider
    this.extraHeaders = options.extraHeaders
    this.extraBody = options.extraBody
    this.researchContext = options.researchContext
    this.chatDebugMetadata = options.chatDebugMetadata
    this.requestScope = options.requestScope
  }

  /**
   * Streaming API used by existing chat modes.
   *
   * This intentionally mirrors the previous `ollama.stream(...)` contract:
   * - yields plain string tokens
   * - optionally calls `callbacks[i].handleLLMEnd(result)` once at the end
   */
  async stream(
    messages: BaseMessage[],
    options?: {
      signal?: AbortSignal
      // Matches the shape used in normalChatMode/search/rag, where
      // callbacks: [{ handleLLMEnd(output) { ... } }]
      callbacks?: Array<{ handleLLMEnd?: (output: any) => any }>
    }
  ): Promise<AsyncGenerator<any, void, unknown>> {
    const { signal, callbacks } = options || {}
    this.serverMessageId = undefined
    this.userServerMessageId = undefined

    const tldwMessages = this.convertToTldwMessages(messages)
    const toolCalls: ToolCall[] = []
    // Captures the background transport's `stream_transport_interrupted`
    // sentinel. TldwChat surfaces it via onChunk (not as a text token), so we
    // hold onto the raw chunk here and re-emit it after the token loop so the
    // chat pipeline can finalize a truncated answer as interrupted.
    let interruptionChunk: Record<string, unknown> | null = null

    const applyToolCallDelta = (deltas: any[]) => {
      deltas.forEach((delta, fallbackIndex) => {
        const index =
          typeof delta?.index === "number" ? delta.index : fallbackIndex
        if (!toolCalls[index]) {
          toolCalls[index] = {
            id: typeof delta?.id === "string" ? delta.id : `tool-${index}`,
            type: "function",
            function: { name: "", arguments: "" }
          }
        }
        if (typeof delta?.id === "string") {
          toolCalls[index].id = delta.id
        }
        if (typeof delta?.type === "string") {
          toolCalls[index].type = delta.type as ToolCall["type"]
        }
        if (delta?.function) {
          if (typeof delta.function.name === "string") {
            toolCalls[index].function.name += delta.function.name
          }
          if (typeof delta.function.arguments === "string") {
            const prevArgs = toolCalls[index].function.arguments || ""
            toolCalls[index].function.arguments = prevArgs + delta.function.arguments
          }
        }
      })
    }

    const handleChunk = (chunk: any) => {
      if (signal?.aborted) return
      const streamedConversationId =
        typeof chunk?.tldw_conversation_id === "string" &&
        chunk.tldw_conversation_id.trim().length > 0
          ? chunk.tldw_conversation_id.trim()
          : typeof chunk?.conversation_id === "string" &&
              chunk.conversation_id.trim().length > 0
            ? chunk.conversation_id.trim()
            : null
      // Nonpersisted completions also carry a request-scoped conversation UUID.
      // It must not turn local history into a link to a nonexistent server chat.
      if (streamedConversationId && this.saveToDb !== false) {
        this.conversationId = streamedConversationId
        this.saveToDb = true
      }
      if (this.saveToDb !== false && typeof chunk?.tldw_message_id === "string") {
        const savedMessageId = chunk.tldw_message_id.trim()
        if (savedMessageId) this.serverMessageId = savedMessageId
      }

      if (this.saveToDb !== false && typeof chunk?.tldw_user_message_id === "string") {
        const savedUserMessageId = chunk.tldw_user_message_id.trim()
        if (savedUserMessageId) this.userServerMessageId = savedUserMessageId
      }

      const loopEvent = extractChatLoopEvent(chunk)
      if (loopEvent) {
        publishChatLoopEvent(loopEvent)
      }

      if (extractStreamTransportInterruption(chunk)) {
        interruptionChunk = chunk as Record<string, unknown>
      }

      const deltas =
        chunk?.choices?.[0]?.delta?.tool_calls ??
        chunk?.choices?.[0]?.tool_calls ??
        chunk?.tool_calls
      if (Array.isArray(deltas)) {
        applyToolCallDelta(deltas)
      }
    }

    const stream = tldwChat.streamMessage(
      tldwMessages,
      {
        // Thread the UI AbortSignal so Stop aborts the underlying request in
        // all modes (not just polling `signal.aborted` at the loop top).
        signal,
        model: this.model,
        temperature: this.temperature,
        maxTokens: this.maxTokens,
        topP: this.topP,
        frequencyPenalty: this.frequencyPenalty,
        presencePenalty: this.presencePenalty,
        systemPrompt: this.systemPrompt,
        stream: true,
        reasoningEffort: this.reasoningEffort,
        routing: this.routing,
        toolChoice: this.toolChoice,
        tools: this.tools,
        saveToDb: this.saveToDb,
        conversationId: this.conversationId,
        historyMessageLimit: this.historyMessageLimit,
        historyMessageOrder: this.historyMessageOrder,
        slashCommandInjectionMode: this.slashCommandInjectionMode,
        apiProvider: this.apiProvider,
        extraHeaders: this.extraHeaders,
        extraBody: this.extraBody,
        researchContext: this.researchContext,
        chatDebugMetadata: this.chatDebugMetadata,
        requestScope: this.requestScope
      },
      handleChunk
    )

    async function* generator() {
      let fullText = ""
      try {
        for await (const token of stream) {
          if (signal?.aborted) {
            break
          }
          if (typeof token !== "string") continue
          fullText += token
          // Downstream chat-modes treat chunks as strings or objects with
          // `content` / `choices[0].delta.content`. Yielding the plain
          // string keeps the simple path working (`typeof chunk === 'string'`).
          yield token
        }
        // The extension port can drop after the first byte; TldwChat surfaces a
        // synthesized `stream_transport_interrupted` sentinel via onChunk rather
        // than as a text token. Re-emit it (as an object chunk) so downstream
        // chat-modes finalize the partial answer as interrupted, not complete.
        if (interruptionChunk && !signal?.aborted) {
          yield interruptionChunk
        }
      } finally {
        // Synthesize a minimal LangChain-style result for handleLLMEnd
        if (callbacks && callbacks.length > 0) {
          const generationInfo =
            toolCalls.length > 0 ? { tool_calls: toolCalls } : undefined
          const result = {
            generations: [[{ text: fullText, generationInfo }]]
          }
          for (const cb of callbacks) {
            try {
              await cb?.handleLLMEnd?.(result)
            } catch {
              // Ignore callback errors to avoid breaking chat flow
            }
          }
        }
      }
    }

    return generator()
  }

  // Non-streaming helper mirroring the LangChain-style _generate,
  // used only internally if needed.
  async generateOnce(
    messages: BaseMessage[],
    options?: { signal?: AbortSignal }
  ): Promise<{ text: string; message: AIMessage }> {
    const tldwMessages = this.convertToTldwMessages(messages)

    const response = await tldwChat.sendMessage(tldwMessages, {
      model: this.model,
      temperature: this.temperature,
      maxTokens: this.maxTokens,
      topP: this.topP,
      frequencyPenalty: this.frequencyPenalty,
      presencePenalty: this.presencePenalty,
      systemPrompt: this.systemPrompt,
      stream: false,
      reasoningEffort: this.reasoningEffort,
      routing: this.routing,
      toolChoice: this.toolChoice,
      tools: this.tools,
      saveToDb: this.saveToDb,
      conversationId: this.conversationId,
      historyMessageLimit: this.historyMessageLimit,
      historyMessageOrder: this.historyMessageOrder,
      slashCommandInjectionMode: this.slashCommandInjectionMode,
      apiProvider: this.apiProvider,
      extraHeaders: this.extraHeaders,
      extraBody: this.extraBody,
      researchContext: this.researchContext,
      chatDebugMetadata: this.chatDebugMetadata,
      requestScope: this.requestScope,
      signal: options?.signal
    })

    return {
      text: response,
      message: new AIMessage(response)
    }
  }

  // We don't rely on BaseChatModel's default stream helper in the current
  // chat pipeline; see the custom `stream` implementation above which
  // matches the expected `ollama.stream` contract.

  /**
   * Non-streaming invoke helper to match the simple `.invoke()` shape used
   * by title generation and other one-off calls.
   */
  async invoke(
    messages: BaseMessage[],
    options?: { signal?: AbortSignal }
  ): Promise<{ content: string }> {
    const { text } = await this.generateOnce(messages, options)
    return { content: text }
  }

  private normalizeImageUrl(
    value: unknown
  ): { url: string; detail?: "auto" | "low" | "high" | null } | null {
    if (typeof value === "string") {
      return { url: value }
    }
    if (value && typeof value === "object") {
      const candidate = value as { url?: unknown; detail?: unknown }
      if (typeof candidate.url === "string") {
        let detail: "auto" | "low" | "high" | null | undefined
        if (
          candidate.detail === "auto" ||
          candidate.detail === "low" ||
          candidate.detail === "high" ||
          candidate.detail === null
        ) {
          detail = candidate.detail as "auto" | "low" | "high" | null
        }
        return detail === undefined
          ? { url: candidate.url }
          : { url: candidate.url, detail }
      }
    }
    return null
  }

  private normalizeContentPart(
    part: unknown
  ): ChatCompletionContentPart | null {
    if (typeof part === "string") {
      return { type: "text", text: part }
    }
    if (!part || typeof part !== "object") {
      return null
    }
    const candidate = part as { type?: unknown; text?: unknown; image_url?: unknown }
    if (candidate.type === "text" && typeof candidate.text === "string") {
      return { type: "text", text: candidate.text }
    }
    if (candidate.type === "image_url") {
      const imageUrl = this.normalizeImageUrl(candidate.image_url)
      if (!imageUrl) return null
      return { type: "image_url", image_url: imageUrl }
    }
    return null
  }

  private coerceTextContent(content: unknown): string {
    if (typeof content === "string") {
      return content
    }
    if (!Array.isArray(content)) {
      return ""
    }
    return content
      .map((item) => {
        if (typeof item === "string") return item
        if (item && typeof item === "object") {
          const candidate = item as { type?: unknown; text?: unknown }
          if (candidate.type === "text" && typeof candidate.text === "string") {
            return candidate.text
          }
        }
        return ""
      })
      .filter(Boolean)
      .join(" ")
  }

  private normalizeUserContent(content: unknown): string | ChatCompletionContentPart[] {
    if (typeof content === "string") {
      return content
    }
    if (!Array.isArray(content)) {
      return ""
    }
    const parts = content
      .map((item) => this.normalizeContentPart(item))
      .filter(Boolean) as ChatCompletionContentPart[]
    if (parts.length === 0) {
      return ""
    }
    const hasImage = parts.some((part) => part.type === "image_url")
    if (!hasImage) {
      return this.coerceTextContent(content)
    }
    return parts
  }

  private convertToTldwMessages(messages: BaseMessage[]): ChatMessage[] {
    return messages.map((msg) => {
      if (msg instanceof SystemMessage) {
        return {
          role: "system",
          content: this.coerceTextContent(msg.content)
        }
      }
      if (msg instanceof ToolMessage) {
        return {
          role: "tool",
          content: this.coerceTextContent(msg.content),
          tool_call_id: msg.tool_call_id
        }
      }
      if (msg instanceof AIMessage) {
        return {
          role: "assistant",
          content: this.coerceTextContent(msg.content)
        }
      }
      if (msg instanceof HumanMessage) {
        return {
          role: "user",
          content: this.supportsMultimodal
            ? this.normalizeUserContent(msg.content)
            : this.coerceTextContent(msg.content)
        }
      }

      return {
        role: "user",
        content: this.coerceTextContent(msg.content)
      }
    })
  }

  // Method to check if tldw is available
  static async isAvailable(): Promise<boolean> {
    try {
      return await tldwChat.isReady()
    } catch {
      return false
    }
  }

  // Method to cancel the current stream
  cancelStream(): void {
    tldwChat.cancelStream()
  }
}

import { beforeEach, describe, expect, it, vi } from "vitest"

import { pageAssistModel } from "../index"
import { tldwModels, type ModelInfo } from "@/services/tldw"
import { useMcpToolsStore } from "@/store/mcp-tools"
import { useStoreChatModelSettings } from "@/store/model"
import { useStoreMessageOption } from "@/store/option"
import { buildChatToolFilterState } from "@/utils/chat-tools"

vi.mock("@/services/model-settings", () => ({
  getAllDefaultModelSettings: vi.fn(async () => ({})),
  getModelSettings: vi.fn(async () => ({}))
}))

vi.mock("@/services/tldw-server", () => ({
  getDefaultApiProvider: vi.fn(async () => "openai")
}))

vi.mock("@/services/tldw", () => ({
  tldwModels: {
    getModel: vi.fn(async () => ({ capabilities: ["tools"] }))
  },
  tldwChat: {
    sendMessage: vi.fn(),
    streamMessage: vi.fn()
  }
}))

vi.mock("@/utils/resolve-api-provider", () => ({
  resolveApiProviderForModel: vi.fn(async () => "openai")
}))

const buildResolvedTools = (tools: Record<string, unknown>[]) =>
  buildChatToolFilterState({ tools }).chatTools

const modelInfo = (capabilities: string[] = ["tools"]): ModelInfo => ({
  id: "tool-model",
  name: "Tool Model",
  provider: "openai",
  type: "chat",
  capabilities
})

describe("pageAssistModel MCP tools", () => {
  beforeEach(() => {
    vi.mocked(tldwModels.getModel).mockResolvedValue(modelInfo(["tools"]))
    useStoreChatModelSettings.getState().reset()
    useStoreMessageOption.setState({
      toolChoice: "auto",
      serverChatId: null,
      temporaryChat: true
    })
    useMcpToolsStore.setState({
      tools: [],
      discoveredTools: [],
      availableTools: [],
      chatTools: [],
      healthState: "healthy",
      toolsLoading: false,
      disabledToolPreferences: { version: 1, scopes: {} },
      activeToolPreferenceScope: "default",
      disabledToolNames: [],
      collisionToolNames: [],
      toolCounts: {
        discovered: 0,
        executable: 0,
        disabled: 0,
        colliding: 0,
        chatEnabled: 0
      }
    })
  })

  it("persists the first saved conversation without requiring an existing server id", async () => {
    useStoreMessageOption.setState({ temporaryChat: false, serverChatId: null })
    const chat = await pageAssistModel({ model: "tool-model" })
    expect(chat.saveToDb).toBe(true)
  })

  it("keeps temporary conversations unpersisted even with a stale server id", async () => {
    useStoreMessageOption.setState({ temporaryChat: true, serverChatId: "old-chat" })
    const chat = await pageAssistModel({ model: "tool-model" })
    expect({ saved: chat.saveToDb, id: chat.conversationId }).toEqual({ saved: false, id: undefined })
  })

  it("uses stored chatTools instead of all executable MCP tools", async () => {
    const notesTool = {
      name: "notes.search",
      description: "Search notes",
      parameters: { type: "object", properties: { q: { type: "string" } } },
      canExecute: true
    }
    const slidesTool = {
      name: "slides.list",
      description: "List slides",
      canExecute: true
    }

    useMcpToolsStore.setState({
      tools: [notesTool, slidesTool],
      chatTools: buildResolvedTools([notesTool])
    })

    const chat = await pageAssistModel({ model: "tool-model" })

    expect(chat.toolChoice).toBe("auto")
    expect(chat.extraHeaders).toEqual({
      "X-TLDW-Loop-Compat": "1"
    })
    expect(chat.chatDebugMetadata).toMatchObject({
      toolChoice: "auto",
      toolCounts: {
        discovered: 1,
        executable: 1,
        disabled: 0,
        colliding: 0,
        chatEnabled: 1
      }
    })
    expect(chat.tools).toEqual([
      {
        type: "function",
        function: {
          name: "notes_search",
          description: "Search notes",
          parameters: {
            type: "object",
            properties: { q: { type: "string" } }
          }
        }
      }
    ])
  })

  it("preserves the captured Service Prompt request scope on the model", async () => {
    const requestScope = {
      config: {
        serverUrl: "https://research-one.test",
        authMode: "multi-user" as const
      },
      userId: 42
    }

    const chat = await pageAssistModel({ model: "tool-model", requestScope })

    expect(chat.requestScope).toBe(requestScope)
  })

  it("omits tool choice and tools when no chat tools remain", async () => {
    useMcpToolsStore.setState({
      tools: [
        {
          name: "notes.search",
          description: "Search notes",
          canExecute: true
        }
      ],
      chatTools: []
    })

    const chat = await pageAssistModel({ model: "tool-model" })

    expect(chat.toolChoice).toBeUndefined()
    expect(chat.tools).toBeUndefined()
    expect(chat.extraHeaders).toBeUndefined()
    expect(chat.chatDebugMetadata?.toolOmissionReason).toBe(
      "no_enabled_executable_tools"
    )
  })

  it("omits tools and loop compatibility when the selected model does not support tools", async () => {
    vi.mocked(tldwModels.getModel).mockResolvedValueOnce(modelInfo([]))
    useMcpToolsStore.setState({
      chatTools: buildResolvedTools([
        {
          name: "notes.search",
          description: "Search notes",
          canExecute: true
        }
      ])
    })

    const chat = await pageAssistModel({ model: "plain-model" })

    expect(chat.toolChoice).toBeUndefined()
    expect(chat.tools).toBeUndefined()
    expect(chat.extraHeaders).toBeUndefined()
    expect(chat.chatDebugMetadata?.toolOmissionReason).toBe(
      "model_lacks_tool_capability"
    )
  })

  it("omits tools and loop compatibility when MCP is unhealthy", async () => {
    useMcpToolsStore.setState({
      healthState: "unhealthy",
      chatTools: buildResolvedTools([
        {
          name: "notes.search",
          description: "Search notes",
          canExecute: true
        }
      ])
    })

    const chat = await pageAssistModel({ model: "tool-model" })

    expect(chat.toolChoice).toBeUndefined()
    expect(chat.tools).toBeUndefined()
    expect(chat.extraHeaders).toBeUndefined()
    expect(chat.chatDebugMetadata?.toolOmissionReason).toBe("mcp_unhealthy")
  })

  it("reports absent MCP when the MCP capability is unavailable", async () => {
    useMcpToolsStore.setState({
      healthState: "unavailable",
      chatTools: buildResolvedTools([
        {
          name: "notes.search",
          description: "Search notes",
          canExecute: true
        }
      ])
    })

    const chat = await pageAssistModel({ model: "tool-model" })

    expect(chat.toolChoice).toBeUndefined()
    expect(chat.tools).toBeUndefined()
    expect(chat.extraHeaders).toBeUndefined()
    expect(chat.chatDebugMetadata?.toolOmissionReason).toBe("mcp_absent")
  })

  it("omits tools and loop compatibility when tool choice is none", async () => {
    useStoreMessageOption.setState({ toolChoice: "none" })
    useMcpToolsStore.setState({
      chatTools: buildResolvedTools([
        {
          name: "notes.search",
          description: "Search notes",
          canExecute: true
        }
      ])
    })

    const chat = await pageAssistModel({ model: "tool-model" })

    expect(chat.toolChoice).toBeUndefined()
    expect(chat.tools).toBeUndefined()
    expect(chat.extraHeaders).toBeUndefined()
    expect(chat.chatDebugMetadata?.toolOmissionReason).toBe("tool_choice_none")
  })

  it("omits collision-only tools and reports the resolver counts", async () => {
    const collisionState = buildChatToolFilterState({
      tools: [
        { name: "docs.search", canExecute: true },
        { name: "docs_search", canExecute: true }
      ]
    })
    useMcpToolsStore.setState({
      tools: collisionState.availableTools.map((tool) => tool.tool as any),
      chatTools: collisionState.chatTools,
      toolCounts: collisionState.counts
    })

    const chat = await pageAssistModel({ model: "tool-model" })

    expect(chat.toolChoice).toBeUndefined()
    expect(chat.tools).toBeUndefined()
    expect(chat.extraHeaders).toBeUndefined()
    expect(chat.chatDebugMetadata).toMatchObject({
      toolOmissionReason: "no_enabled_executable_tools",
      toolCounts: {
        discovered: 2,
        executable: 2,
        disabled: 0,
        colliding: 2,
        chatEnabled: 0
      }
    })
  })
})

import {
  tldwClient,
  ChatMessage,
  ChatCompletionRequest,
  type ChatCompletionContentPart,
  type ChatResearchContext
} from "./TldwApiClient"
import { extractTokenFromChunk } from "@/utils/extract-token-from-chunk"
import {
  captureChatRequestDebugSnapshot,
  getLastChatCompletionDebugSnapshot,
  type ChatCompletionDebugSnapshot,
  type ChatRequestDebugMetadata
} from "./chat-request-debug"
import { normalizeChatToolsForRequest } from "@/utils/chat-tools"
import type { ServicePromptRequestScope } from "./domains/service-prompts"
import { isRequestConfigScopeChangedError } from "./service-prompt-scope-error"

const normalizeProvider = (value?: string): string =>
  String(value || "").trim().toLowerCase()

const shouldUseTextParts = (provider?: string, model?: string): boolean => {
  const normalized = normalizeProvider(provider)
  if (normalized) return normalized === "google" || normalized === "gemini"
  const normalizedModel = String(model || "").toLowerCase()
  return normalizedModel.includes("gemini")
}

const normalizeMessagesForProvider = (
  messages: ChatMessage[],
  provider?: string,
  model?: string
): ChatMessage[] => {
  if (!shouldUseTextParts(provider, model)) return messages
  return messages.map((msg) => {
    if (msg.role !== "user") return msg
    if (typeof msg.content === "string") {
      return {
        ...msg,
        content: [{ type: "text", text: msg.content }]
      }
    }
    return msg
  })
}

const normalizeSystemPrompt = (value?: string): string | undefined => {
  if (typeof value !== "string") return undefined
  const trimmed = value.trim()
  return trimmed.length > 0 ? trimmed : undefined
}

const coercePositiveTimeout = (
  value: unknown,
  fallback: number
): number => {
  if (typeof value === "number" && Number.isFinite(value) && value > 0) {
    return Math.trunc(value)
  }
  return fallback
}

const hasReasoningProgress = (chunk: unknown): boolean => {
  if (!chunk || typeof chunk !== "object") return false
  const record = chunk as Record<string, unknown>
  const reasoningDelta =
    (record.choices as Array<Record<string, unknown>> | undefined)?.[0]?.delta &&
    typeof (record.choices as Array<Record<string, unknown>>)[0]?.delta === "object"
      ? (
          (record.choices as Array<Record<string, unknown>>)[0]
            ?.delta as Record<string, unknown>
        )?.reasoning_content
      : undefined
  if (typeof reasoningDelta === "string" && reasoningDelta.length > 0) {
    return true
  }
  const additionalKwargs =
    typeof record.additional_kwargs === "object" &&
    record.additional_kwargs !== null
      ? (record.additional_kwargs as Record<string, unknown>)
      : null
  return Boolean(
    typeof additionalKwargs?.reasoning_content === "string" &&
      additionalKwargs.reasoning_content.length > 0
  )
}

const hasVisibleAssistantProgress = (chunk: unknown): boolean =>
  extractTokenFromChunk(chunk).length > 0 || hasReasoningProgress(chunk)

const readErrorMessage = (error: unknown, fallback = "Aborted"): string => {
  const seen = new Set<unknown>()
  let current: unknown = error
  let firstMessage: string | null = null

  while (current && !seen.has(current)) {
    seen.add(current)
    if (current instanceof Error && current.message) {
      firstMessage ??= current.message
      if (current.name === "AbortError") return current.message
      if (current.message.toLowerCase().includes("abort")) return current.message
    }
    current = (current as { cause?: unknown } | null)?.cause
  }

  return firstMessage ?? fallback
}

const isAbortLikeError = (error: unknown): boolean => {
  const seen = new Set<unknown>()
  let current: unknown = error

  while (current && !seen.has(current)) {
    seen.add(current)
    if (current instanceof Error) {
      if (current.name === "AbortError") return true
      if (current.message.toLowerCase().includes("abort")) return true
    }
    current = (current as { cause?: unknown } | null)?.cause
  }
  return false
}

const createAbortError = (message = "Aborted"): Error => {
  const abortError = new Error(message)
  abortError.name = "AbortError"
  return abortError
}

const resolveStreamTimeoutError = (
  reason: "startup" | "idle" | null,
  sawVisibleProgress: boolean
): Error | null => {
  if (reason === "startup" && !sawVisibleProgress) {
    return new Error("Chat response timed out before any visible output arrived.")
  }
  if (reason === "idle") {
    return new Error("Chat response stalled after visible output began.")
  }
  return null
}

const sanitizeUserContent = (
  content: string | ChatCompletionContentPart[]
): string | ChatCompletionContentPart[] | null => {
  if (typeof content === "string") {
    const trimmed = content.trim()
    return trimmed.length > 0 ? trimmed : null
  }
  if (!Array.isArray(content)) return null

  const cleaned = content
    .map((part) => {
      if (!part || typeof part !== "object") return null
      if (part.type === "text") {
        const text = typeof part.text === "string" ? part.text.trim() : ""
        return text.length > 0 ? { type: "text", text } : null
      }
      if (part.type === "image_url") {
        const candidate = part.image_url
        const url = typeof candidate?.url === "string" ? candidate.url.trim() : ""
        if (!url) return null
        const detail = candidate?.detail
        if (detail === "auto" || detail === "low" || detail === "high" || detail === null) {
          return { type: "image_url", image_url: { url, detail } }
        }
        return { type: "image_url", image_url: { url } }
      }
      return null
    })
    .filter(Boolean) as ChatCompletionContentPart[]

  return cleaned.length > 0 ? cleaned : null
}

const sanitizeMessages = (messages: ChatMessage[]): ChatMessage[] => {
  return messages
    .map((message) => {
      if (message.role === "system") {
        const content = message.content.trim()
        if (!content) return null
        return { ...message, content }
      }

      if (message.role === "user") {
        const content = sanitizeUserContent(message.content)
        if (content == null) return null
        return { ...message, content } as ChatMessage
      }

      if (message.role === "assistant") {
        const content =
          typeof message.content === "string"
            ? message.content.trim()
            : message.content
        const hasToolCalls =
          Array.isArray(message.tool_calls) && message.tool_calls.length > 0
        const hasFunctionCall =
          typeof message.function_call?.name === "string" &&
          message.function_call.name.trim().length > 0
        if (typeof content === "string" && content.length > 0) {
          return { ...message, content }
        }
        if (hasToolCalls || hasFunctionCall) {
          return { ...message, content: null }
        }
        return null
      }

      const rawToolCallId = (message as any).tool_call_id
      const toolCallId =
        typeof rawToolCallId === "string" ? rawToolCallId.trim() : ""
      const rawContent = message.content
      const content =
        typeof rawContent === "string" ? rawContent.trim() : ""
      if (!toolCallId || !content) return null
      return { ...message, tool_call_id: toolCallId, content }
    })
    .filter(Boolean) as ChatMessage[]
}

const buildRequestMessages = (
  messages: ChatMessage[],
  options: TldwChatOptions
): ChatMessage[] => {
  const sanitizedMessages = sanitizeMessages(messages)
  const systemPrompt = normalizeSystemPrompt(options.systemPrompt)
  let withSystemPrompt: ChatMessage[]
  if (systemPrompt) {
    if (sanitizedMessages[0]?.role === "system") {
      // Replace existing system message with the user-configured one
      withSystemPrompt = [
        { role: "system", content: systemPrompt } as ChatMessage,
        ...sanitizedMessages.slice(1)
      ]
    } else {
      withSystemPrompt = [
        { role: "system", content: systemPrompt } as ChatMessage,
        ...sanitizedMessages
      ]
    }
  } else {
    withSystemPrompt = sanitizedMessages
  }

  return normalizeMessagesForProvider(
    withSystemPrompt,
    options.apiProvider,
    options.model
  )
}

export interface TldwChatOptions {
  model: string
  routing?: ChatCompletionRequest["routing"]
  temperature?: number
  logprobs?: boolean
  topLogprobs?: number
  maxTokens?: number
  topP?: number
  frequencyPenalty?: number
  presencePenalty?: number
  stream?: boolean
  systemPrompt?: string
  reasoningEffort?: "low" | "medium" | "high"
  toolChoice?: "auto" | "none" | "required"
  tools?: Record<string, unknown>[]
  saveToDb?: boolean
  conversationId?: string
  historyMessageLimit?: number
  historyMessageOrder?: string
  slashCommandInjectionMode?: string
  apiProvider?: string
  extraHeaders?: Record<string, unknown>
  extraBody?: Record<string, unknown>
  thinkingBudgetTokens?: number
  grammarMode?: "none" | "library" | "inline"
  grammarId?: string
  grammarInline?: string
  grammarOverride?: string
  jsonMode?: boolean
  researchContext?: ChatResearchContext
  chatDebugMetadata?: ChatRequestDebugMetadata
  // Caller-owned AbortSignal (e.g. the UI Stop signal). When it fires, the
  // internal per-call controller is aborted so the underlying request stops.
  signal?: AbortSignal
  requestScope?: ServicePromptRequestScope
}
export { getLastChatCompletionDebugSnapshot }
export type { ChatCompletionDebugSnapshot }

export interface ChatStreamChunk {
  id?: string
  object?: string
  created?: number
  model?: string
  choices?: Array<{
    index: number
    delta: {
      role?: string
      content?: string
      tool_calls?: Array<{
        index?: number
        id?: string
        type?: "function"
        function?: {
          name?: string
          arguments?: string
        }
      }>
    }
    logprobs?: {
      content?: Array<{
        token?: string
        logprob?: number
        top_logprobs?: Array<{
          token?: string
          logprob?: number
        }>
      }>
      tokens?: string[]
      token_logprobs?: number[]
      top_logprobs?: Array<Record<string, number>>
    }
    finish_reason?: string | null
  }>
}

export class TldwChatService {
  // Per-call controllers are tracked here so that `cancelStream()` can act as a
  // global "stop everything" without any single call clobbering another. Each
  // `streamMessage` invocation owns its own controller (see below); we never
  // share one controller across concurrent streams (Compare mode, double-send).
  private activeControllers: Set<AbortController> = new Set()

  /**
   * Send a chat completion request
   */
  async sendMessage(
    messages: ChatMessage[],
    options: TldwChatOptions,
    onResponse?: (response: unknown) => void
  ): Promise<string> {
    try {
      await tldwClient.initialize()
      const normalizedTools =
        options.toolChoice === "none"
          ? undefined
          : normalizeChatToolsForRequest(options.tools)
      const toolChoice =
        normalizedTools &&
        (options.toolChoice === "auto" || options.toolChoice === "required")
          ? options.toolChoice
          : undefined
      const requestMessages = buildRequestMessages(messages, options)
      if (requestMessages.length === 0) {
        throw new Error(
          "Cannot send chat request without any messages. Add a user message or a system prompt."
        )
      }

      const request: ChatCompletionRequest = {
        messages: requestMessages,
        model: options.model,
        routing: options.routing,
        stream: false,
        temperature: options.temperature,
        logprobs: options.logprobs,
        top_logprobs:
          options.logprobs && Number.isFinite(options.topLogprobs)
            ? options.topLogprobs
            : undefined,
        max_tokens: options.maxTokens,
        top_p: options.topP,
        frequency_penalty: options.frequencyPenalty,
        presence_penalty: options.presencePenalty,
        reasoning_effort: options.reasoningEffort,
        ...(normalizedTools
          ? {
              ...(toolChoice ? { tool_choice: toolChoice } : {}),
              tools: normalizedTools
            }
          : {}),
        save_to_db: options.saveToDb,
        conversation_id: options.conversationId,
        history_message_limit: options.historyMessageLimit,
        history_message_order: options.historyMessageOrder,
        slash_command_injection_mode: options.slashCommandInjectionMode,
        api_provider: options.apiProvider,
        extra_headers: options.extraHeaders,
        extra_body: options.extraBody,
        thinking_budget_tokens: options.thinkingBudgetTokens,
        grammar_mode: options.grammarMode,
        grammar_id: options.grammarId,
        grammar_inline: options.grammarInline,
        grammar_override: options.grammarOverride,
        response_format: options.jsonMode ? { type: "json_object" } : undefined,
        research_context: options.researchContext
      }
      captureChatRequestDebugSnapshot({
        endpoint: "/api/v1/chat/completions",
        method: "POST",
        mode: "non-stream",
        body: request,
        metadata: options.chatDebugMetadata
      })

      const response = await tldwClient.createChatCompletion(request, {
        debugMetadata: options.chatDebugMetadata,
        signal: options.signal,
        requestScope: options.requestScope
      })
      const data = await response.json().catch(() => null)
      if (onResponse) {
        onResponse(data)
      }
      const content = data?.choices?.[0]?.message?.content || data?.content || data?.text
      if (typeof content === 'string') {
        return content
      }
      throw new Error('Invalid response format from tldw server')
    } catch (error) {
      if (isAbortLikeError(error) || isRequestConfigScopeChangedError(error)) {
        throw error
      }
      console.error('Chat completion failed:', error)
      throw new Error('Chat completion failed', { cause: error })
    }
  }

  /**
   * Send a streaming chat completion request
   */
  async *streamMessage(
    messages: ChatMessage[],
    options: TldwChatOptions,
    onChunk?: (chunk: ChatStreamChunk) => void
  ): AsyncGenerator<string, void, unknown> {
    // Per-call abort controller: concurrent streams must not cancel each other.
    const controller = new AbortController()
    this.activeControllers.add(controller)

    // Combine the caller's signal (e.g. the UI Stop signal) with this call's
    // controller so a Stop actually aborts the underlying request/transport,
    // while internal timeouts abort only this call (not the caller's signal).
    const callerSignal = options.signal
    let detachCallerSignal: (() => void) | null = null
    if (callerSignal) {
      if (callerSignal.aborted) {
        controller.abort()
      } else {
        const onCallerAbort = () => controller.abort()
        callerSignal.addEventListener("abort", onCallerAbort, { once: true })
        detachCallerSignal = () =>
          callerSignal.removeEventListener("abort", onCallerAbort)
      }
    }

    try {
      await tldwClient.initialize()
      const normalizedTools =
        options.toolChoice === "none"
          ? undefined
          : normalizeChatToolsForRequest(options.tools)
      const toolChoice =
        normalizedTools &&
        (options.toolChoice === "auto" || options.toolChoice === "required")
          ? options.toolChoice
          : undefined
      const requestMessages = buildRequestMessages(messages, options)
      if (requestMessages.length === 0) {
        throw new Error(
          "Cannot send chat request without any messages. Add a user message or a system prompt."
        )
      }

      const cfg = (await tldwClient.getConfig().catch(() => null)) as
        | {
            chatRequestTimeoutMs?: number
            chatStartupTimeoutMs?: number
            chatStreamIdleTimeoutMs?: number
          }
        | null

      const request: ChatCompletionRequest = {
        messages: requestMessages,
        model: options.model,
        routing: options.routing,
        stream: true,
        temperature: options.temperature,
        logprobs: options.logprobs,
        top_logprobs:
          options.logprobs && Number.isFinite(options.topLogprobs)
            ? options.topLogprobs
            : undefined,
        max_tokens: options.maxTokens,
        top_p: options.topP,
        frequency_penalty: options.frequencyPenalty,
        presence_penalty: options.presencePenalty,
        reasoning_effort: options.reasoningEffort,
        ...(normalizedTools
          ? {
              ...(toolChoice ? { tool_choice: toolChoice } : {}),
              tools: normalizedTools
            }
          : {}),
        save_to_db: options.saveToDb,
        conversation_id: options.conversationId,
        history_message_limit: options.historyMessageLimit,
        history_message_order: options.historyMessageOrder,
        slash_command_injection_mode: options.slashCommandInjectionMode,
        api_provider: options.apiProvider,
        extra_headers: options.extraHeaders,
        extra_body: options.extraBody,
        thinking_budget_tokens: options.thinkingBudgetTokens,
        grammar_mode: options.grammarMode,
        grammar_id: options.grammarId,
        grammar_inline: options.grammarInline,
        grammar_override: options.grammarOverride,
        response_format: options.jsonMode ? { type: "json_object" } : undefined,
        research_context: options.researchContext
      }
      captureChatRequestDebugSnapshot({
        endpoint: "/api/v1/chat/completions",
        method: "POST",
        mode: "stream",
        body: request,
        metadata: options.chatDebugMetadata
      })

      const startupTimeoutMs = coercePositiveTimeout(
        cfg?.chatStartupTimeoutMs,
        10_000
      )
      const streamIdleTimeoutMs = coercePositiveTimeout(
        cfg?.chatStreamIdleTimeoutMs,
        30_000
      )
      const stream = tldwClient.streamChatCompletion(request, {
        signal: controller.signal,
        streamIdleTimeoutMs,
        debugMetadata: options.chatDebugMetadata,
        requestScope: options.requestScope
      })

      let idleTimer: ReturnType<typeof setTimeout> | null = null
      let startupTimer: ReturnType<typeof setTimeout> | null = null
      let sawVisibleProgress = false
      let timeoutReason: "startup" | "idle" | null = null

      const clearIdleTimer = () => {
        if (idleTimer) {
          clearTimeout(idleTimer)
          idleTimer = null
        }
      }

      const clearStartupTimer = () => {
        if (startupTimer) {
          clearTimeout(startupTimer)
          startupTimer = null
        }
      }

      const abortForTimeout = (reason: "startup" | "idle") => {
        timeoutReason = reason
        controller?.abort()
      }

      const armStartupTimer = () => {
        clearStartupTimer()
        startupTimer = setTimeout(() => {
          abortForTimeout("startup")
        }, startupTimeoutMs)
      }

      const resetIdleTimer = () => {
        clearIdleTimer()
        idleTimer = setTimeout(() => {
          abortForTimeout("idle")
        }, streamIdleTimeoutMs)
      }

      try {
        armStartupTimer()
        try {
          for await (const chunk of stream) {
            if (hasVisibleAssistantProgress(chunk)) {
              sawVisibleProgress = true
              clearStartupTimer()
              resetIdleTimer()
            }

            // Check if stream was cancelled
            if (controller?.signal.aborted) {
              break
            }

            // Call the onChunk callback if provided
            if (onChunk) {
              onChunk(chunk)
            }

            const token = extractTokenFromChunk(chunk)
            if (token) {
              yield token
            }
          }
        } catch (error) {
          const timeoutError = resolveStreamTimeoutError(
            timeoutReason,
            sawVisibleProgress
          )
          if (timeoutError) {
            throw timeoutError
          }
          if (controller?.signal.aborted && isAbortLikeError(error)) {
            throw createAbortError(readErrorMessage(error))
          }
          throw error
        }
        const timeoutError = resolveStreamTimeoutError(
          timeoutReason,
          sawVisibleProgress
        )
        if (timeoutError) {
          throw timeoutError
        }
        if (controller?.signal.aborted) {
          throw createAbortError()
        }
      } finally {
        clearIdleTimer()
        clearStartupTimer()
      }
    } catch (error) {
      console.warn('Stream completion failed:', readErrorMessage(error))
      if (isRequestConfigScopeChangedError(error)) throw error
      if (isAbortLikeError(error)) {
        throw createAbortError(readErrorMessage(error))
      }
      throw new Error('Stream completion failed', { cause: error })
    } finally {
      this.activeControllers.delete(controller)
      detachCallerSignal?.()
    }
  }

  /**
   * Cancel all in-flight streaming requests.
   *
   * This is a global "stop everything" used by external callers. New streams no
   * longer auto-invoke this, so starting a stream never cancels other in-flight
   * streams (Compare mode, double-send, regenerate-while-streaming).
   */
  cancelStream(): void {
    for (const controller of this.activeControllers) {
      controller.abort()
    }
    this.activeControllers.clear()
  }

  /**
   * Create a conversation with context
   */
  buildConversation(
    history: ChatMessage[],
    newMessage: string,
    systemPrompt?: string
  ): ChatMessage[] {
    const messages: ChatMessage[] = []

    // Add system prompt if provided
    if (systemPrompt) {
      messages.push({ role: 'system', content: systemPrompt })
    }

    // Add history
    messages.push(...history)

    // Add new user message
    messages.push({ role: 'user', content: newMessage })

    return messages
  }

  /**
   * Format a response for display
   */
  formatResponse(content: string): string {
    // Basic formatting - can be enhanced
    return content.trim()
  }

  /**
   * Check if the service is ready
   */
  async isReady(): Promise<boolean> {
    try {
      await tldwClient.initialize()
      return await tldwClient.healthCheck()
    } catch {
      return false
    }
  }

  /**
   * Get token estimate for messages
   * This is a rough estimate - actual tokens depend on the model
   */
  estimateTokens(messages: ChatMessage[]): number {
    let totalChars = 0
    for (const msg of messages) {
      const content = msg.content
      if (typeof content === "string") {
        totalChars += content.length
      } else if (Array.isArray(content)) {
        let partTokens = 0
        for (const part of content as any[]) {
          if (typeof part === "string") {
            partTokens += part.length
          } else if (part?.type === "text" && typeof part.text === "string") {
            partTokens += part.text.length
          } else if (part?.type === "image_url") {
            // Rough image token estimate: 85 tokens for low detail, 765 for high
            const detail = part.image_url?.detail
            const imageTokens = detail === "low" ? 85 : 765
            partTokens += imageTokens * 4 // convert to char-equivalents
          }
        }
        totalChars += partTokens
      } else if (content != null) {
        try {
          totalChars += JSON.stringify(content).length
        } catch {
          // Fallback if serialization fails
        }
      }
    }
    // Rough estimate: 1 token ≈ 4 characters
    return Math.ceil(totalChars / 4)
  }

  /**
   * Truncate messages to fit within token limit
   */
  truncateMessages(
    messages: ChatMessage[],
    maxTokens: number,
    keepSystemPrompt: boolean = true
  ): ChatMessage[] {
    const result: ChatMessage[] = []
    let currentTokens = 0

    // Keep system prompt if requested
    if (keepSystemPrompt && messages[0]?.role === 'system') {
      result.push(messages[0])
      currentTokens += this.estimateTokens([messages[0]])
    }

    // Add messages from the end (most recent first)
    for (let i = messages.length - 1; i >= 0; i--) {
      const msg = messages[i]

      // Skip system prompt if already added
      if (msg.role === 'system' && result.length > 0 && result[0].role === 'system') {
        continue
      }

      const msgTokens = this.estimateTokens([msg])
      if (currentTokens + msgTokens <= maxTokens) {
        result.splice(keepSystemPrompt ? 1 : 0, 0, msg)
        currentTokens += msgTokens
      } else {
        break
      }
    }

    return result
  }
}

// Singleton instance
export const tldwChat = new TldwChatService()
